n_status not in ('evidence_supported','verified_reference') or evidence_ref is not null)); create table if not exists public.setc_insurance_compliance_assessments (insurance_compliance_assessment_id uuid primary key default gen_random_uuid(),organization_oid text not null references public.setc_organizations(oid),insurance_compliance_obligation_id uuid not null references public.setc_insurance_compliance_obligations(insurance_compliance_obligation_id),assessment_period_start date,assessment_period_end date,assessment_status text not null default 'not_assessed' check(assessment_status in ('not_assessed','in_review','gap_identified','evidence_supported','compliant_reference','noncompliant_reference','not_applicable_reference','superseded','void')),finding_reference text,remediation_reference text,evidence_ref text,assessed_at timestamptz,created_at timestamptz not null default now(),unique(organization_oid,insurance_compliance_obligation_id,assessment_period_start,assessment_period_end),check(assessment_period_end is null or assessment_period_start is null or assessment_period_end>=assessment_period_start),check(assessment_status not in ('evidence_supported','compliant_reference','noncompliant_reference','not_applicable_reference') or evidence_ref is not null)); create table if not exists public.setc_insurance_regulatory_filings (insurance_regulatory_filing_id uuid primary key default gen_random_uuid(),organization_oid text not null references public.setc_organizations(oid),insurance_regulatory_authority_id uuid references public.setc_insurance_regulatory_authorities(insurance_regulatory_authority_id),jurisdiction_code text not null,filing_type text not null check(filing_type in ('license_application','renewal','financial_statement','solvency','market_conduct','product','rate','claims','reinsurance','cybersecurity','incident','data_privacy','tax','other')),filing_period_start date,filing_period_end date,filing_reference text not null,filing_status text not null defaul